	for name, value := range map[string]string{"E2E_MANAGEMENT_CREDENTIAL": e.Credential, "E2E_USER_ID": e.UserID, "E2E_ORGANIZATION_ID": e.OrganizationID, "E2E_API_KEY": e.APIKey, "E2E_DASHBOARD_URL": e.DashboardURL} {
