		if err != nil || u.Scheme != "https" || u.Host == "" || u.User != nil || u.RawQuery != "" || u.Fragment != "" || (u.Path != "" && u.Path != "/") {
			return nil, errors.New("production endpoints must be HTTPS origins without userinfo, path, query or fragment")
		}
	}
	return e, nil
}

