	if got := recorder.take(); len(got) != 0 {
		t.Fatalf("requests at 77%% = %v, want none", got)
	}

	// At 74% it resolves.
	tick(allocator, 37000)
	if got := recorder.take(); !slices.Equal(got, resolveWarning) {
		t.Fatalf("requests at 74%% = %v, want %v", got, resolveWarning)
