		return cellspec.Spec{Schema: cellspec.Schema, Generation: 1, RequiresBinary: 1, Services: []cellspec.Service{web},
			HostGrants: []cellspec.HostGrant{{Node: node, PrivateIP: ip, Roles: roles, Environment: "canary"}}}
	}
